  ex=[("Volgende week heb ik een proefdag.","Na próxima semana tenho um dia experimental."),("Ik mag een dag meelopen met een collega.","Posso acompanhar um colega durante um dia."),("Je maakt kennis met het team.","Ficas a conhecer a equipa."),("Zo kun je de sfeer proeven.","Assim podes sentir o ambiente.")],
  review=["v-kennismaken","v-team","v-sfeer"],
