    TR("pt-nl","Entre, sente-se.", ["Komt u binnen, gaat u zitten","Kom binnen, ga zitten","Komt u binnen en gaat u zitten"], "Imperativo formal com u.", ["v-binnenkomen"]),
    CJ("afsluiten","wij","Daarna hebben we het gesprek ___.", ["afgesloten"], "af-ge-sloten.", ["v-afsluiten"], tense="passado-perfeito"),
    FB("Het was een ___ prettige kennismaking.", ["wederzijds"], "Advérbio diante de adjetivo: sem -e.", ["v-wederzijds"], choices=["wederzijds","wederzijdse","binnen"], tr="Foi um conhecimento agradável para ambas as partes."),
    DL([("Manager","Heeft u nog vragen voor ons?","Tem mais alguma pergunta para nós?"),("Kandidaat","","")], ["*Ja, hoe ziet een gewone werkdag eruit, en wanneer hoor ik meer over het vervolg?","Nee.|Pouco interessado.","Hoeveel vakantiedagen krijg ik? Dat is het belangrijkste.|Mau foco."], "Perguntas finais inteligentes.", ["v-afsluiten"]),
